import json
from src.nodes.base import BaseNode
from src.runtime import mcp_runtime

class MCPCallToolNode(BaseNode):
    name = "MCP: Call Tool"
    category = "MCP"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("server_name", "string", widget_type="text", default="default")
        self.add_input("tool_name", "string", widget_type="text", default="")
        self.add_input("arguments_json", "string", widget_type="text", default="{}")
        self.add_output("result", "any")
        self.add_output("result_json", "string")
        self.add_output("is_error", "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        server_name = (inputs.get("server_name") or "default").strip() or "default"
        tool_name = (inputs.get("tool_name") or "").strip()
        if not tool_name:
            self.log_error("tool_name is required.")
            return {"result": None, "result_json": "", "is_error": True, "exec_out": True}

        raw_args = inputs.get("arguments_json") or "{}"
        if isinstance(raw_args, dict):
            arguments = raw_args
        else:
            try:
                arguments = json.loads(raw_args) if raw_args.strip() else {}
            except json.JSONDecodeError as exc:
                self.log_error(f"arguments_json is not valid JSON: {exc}. Defaulting to {{}}.")
                arguments = {}
            if not isinstance(arguments, dict):
                self.log_error("arguments_json must decode to a JSON object. Defaulting to {}.")
                arguments = {}

        try:
            result = await mcp_runtime.call_tool(server_name, tool_name, arguments)
        except Exception as exc:
            self.log_error(f"MCP call_tool failed: {exc}")
            return {"result": None, "result_json": "", "is_error": True, "exec_out": True}

        is_error = bool(result.get("is_error"))
        if is_error:
            self.log_error(f"MCP tool '{tool_name}' returned an error.")
        else:
            self.log_info(f"MCP tool '{tool_name}' completed.")
        return {
            "result": result.get("result"),
            "result_json": result.get("result_json") or "",
            "is_error": is_error,
            "exec_out": True,
        }

def register_node():
    return MCPCallToolNode
